use fast_paillier::{DecryptionKey, precomputed_table::PrecomputeTable};
use rug::Integer;
use std::sync::Mutex;
use once_cell::sync::Lazy;
use bencher::{benchmark_group, benchmark_main, Bencher};

static BLOCK_SIZE: usize = 15;
static POW_SIZE: usize = 448;
static PRECOMPUTE_TABLE: Lazy<Mutex<PrecomputeTable>> = Lazy::new(|| {
    let base = Integer::from_str_radix("", 10).unwrap();
    let modulo = Integer::from_str_radix("", 10).unwrap();
    Mutex::new(PrecomputeTable::new_dp(
        base,
        BLOCK_SIZE,
        POW_SIZE,
        modulo,
    ))
});

fn get_precompute_table() -> &'static Mutex<PrecomputeTable> {
    &PRECOMPUTE_TABLE
}

fn encryption_precompute(b: &mut Bencher) {
    let dk = DecryptionKey::sample_112();
    let ek = dk.encryption_key();

    let precompute_table = get_precompute_table();
    
    b.iter(|| {
        let m = Integer::from(10);
        let table = precompute_table.lock().unwrap();
        let mut rng = rand_dev::DevRng::new();
        let _ = ek.encrypt_with_precompute_table(&mut rng, &table, &m).unwrap();
    });
}

benchmark_group!(benches, encryption_precompute);
benchmark_main!(benches);
